        "originalUrl": "https://cdn.discordapp.com/attachments/1269536886586609695/1346014878871195658/dont_give_up.mp4?ex=6aff47ca&is=6afdf64a&hm=7a1a1feb0455ea6bbbb9db0317b3a15c8b15533bdb18bfd4553ea35320fdcbd8&",
